import { loadState, saveState, resetDemo, money, num, fmtDate, roleLabel, permissionsByRole, nextId } from './store.js';
import { bulkDefinitions, parseClipboard, validateRows, applyRows, downloadTemplate } from './bulk.js';
import { isSupabaseConfigured, supabaseLogin, supabaseLogout, loadSupabaseWorkspace, loadTenantDataIntoState, syncTenantToSupabase, createSupabaseShop, callAdminUsers } from './supabase.js';

let state = loadState();
let route = 'dashboard';
let ui = { productSearch:'', productCategory:'all', posSearch:'', cart:[], bulkType:'products', bulkRows:[], bulkText:'', selectedCustomer:'c1', mobileNav:false };
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
const tenantId = () => state.currentTenantId || 'tenant-demo';
const me = () => state.users.find(u => u.id === state.session?.userId);
const shop = () => state.shops.find(s => s.id === tenantId()) || state.shops[0];
const tenantData = key => (state[key] || []).filter(x => x.tenantId === tenantId());
const can = permission => {
  const user = me(); if (!user) return false;
  const p = permissionsByRole[user.role] || [];
  return p.includes('*') || p.includes(permission);
};

const pageInfo = {
  dashboard:['Command Center','Live business pulse, risks and action points.'],
  sales:['Sales & POS','Fast billing, quotations, orders and credit sales.'],
  products:['Products','Item master, UOM, pricing, barcode and stock controls.'],
  inventory:['Inventory','Stock ledger, locations, adjustments and counts.'],
  purchasing:['Purchasing','Purchase orders, GRN, cost control and supplier planning.'],
  customers:['Customers','Credit, ledgers, price groups and follow-ups.'],
  suppliers:['Suppliers','Payables, purchasing history and supplier terms.'],
  delivery:['Delivery','Pick, load, dispatch and proof-of-delivery workflow.'],
  warranty:['Warranty & Serial','Serial-controlled warranty claims and service status.'],
  finance:['Finance','Receivables, payables, expenses, cash and bank control.'],
  reports:['Reports','Operational, stock, profit and management intelligence.'],
  bulk:['Bulk Data Center','Excel templates, paste/import, validation and safe bulk updates.'],
  users:['User Management','Accounts, roles, access, reset and support controls.'],
  shops:['Shop Management','Create and manage tenant shops from Super Admin.'],
  settings:['Settings','Business, tax, security and deployment configuration.']
};

const navGroups = [
  ['WORKSPACE', [['dashboard','⌂','Dashboard'],['sales','▣','Sales & POS'],['products','◇','Products'],['inventory','▦','Inventory'],['purchasing','⇄','Purchasing']]],
  ['RELATIONSHIPS', [['customers','◎','Customers'],['suppliers','◉','Suppliers'],['delivery','➜','Delivery'],['warranty','✦','Warranty']]],
  ['CONTROL', [['finance','◫','Finance'],['reports','⌁','Reports'],['bulk','↥','Bulk Data'],['users','♙','Users'],['shops','◆','Shops'],['settings','⚙','Settings']]]
];

function persist(render=true) { saveState(state); if (state.session?.mode==='supabase' && tenantId()) syncTenantToSupabase(state,tenantId()).catch(err=>toast('Supabase sync warning',err.message,'error')); if (render) renderApp(); }
function toast(title, body='', kind='success') {
  const el=document.createElement('div'); el.className=`toast ${kind}`; el.innerHTML=`<strong>${esc(title)}</strong>${body?`<p>${esc(body)}</p>`:''}`;
  $('#toast-root').appendChild(el); setTimeout(()=>{ el.style.opacity='0'; el.style.transform='translateX(10px)'; setTimeout(()=>el.remove(),250); },3300);
}
function status(v) { return `<span class="status ${esc(String(v).toLowerCase().replaceAll(' ','_'))}">${esc(String(v).replaceAll('_',' '))}</span>`; }
function initials(name) { return String(name||'?').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase(); }
function percent(n,d) { return d ? ((n/d)*100).toFixed(1) : '0.0'; }
function modal(title, subtitle, body, footer='', size='') {
  const wrap=document.createElement('div'); wrap.className='modal-backdrop'; wrap.innerHTML=`<div class="modal ${size}"><div class="modal-head"><div><h3>${title}</h3><p>${subtitle}</p></div><button class="close-btn" data-close>×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</div>`;
  document.body.appendChild(wrap); wrap.addEventListener('click',e=>{ if(e.target===wrap || e.target.closest('[data-close]')) wrap.remove(); }); return wrap;
}

function renderLogin() {
  $('#app').innerHTML=`<div class="login-page fade-in">
    <section class="login-showcase">
      <div class="brand-wrap"><div class="brand-mark">HE</div><div><div class="brand-title">Hardware ERP</div><div class="brand-sub">Retail • Inventory • Finance • Control</div></div></div>
      <h1>Run the whole shop from one <span class="gradient-text">beautiful command center.</span></h1>
      <p>Built for Sri Lankan hardware retail: multi-UOM stock, POS, purchasing, contractor credit, delivery, warranty, audit controls and multi-shop administration.</p>
      <div class="feature-chips"><span class="feature-chip">Multi-shop ready</span><span class="feature-chip">Excel bulk updates</span><span class="feature-chip">Stock movement ledger</span><span class="feature-chip">Credit controls</span><span class="feature-chip">Responsive web app</span></div>
    </section>
    <section class="login-panel-wrap"><form class="login-card" id="login-form">
      <h2>Welcome back</h2><p>Sign in to continue to your workspace.</p>
      <div class="login-field"><label>USERNAME</label><input class="input" id="login-user" autocomplete="username" value="Admin@123" required></div>
      <div class="login-field"><label>PASSWORD</label><input class="input" id="login-pass" type="password" autocomplete="current-password" value="Admin@123#" required></div>
      <button class="login-btn">Sign in securely →</button>
      <div class="demo-credential"><strong>Demo Super Admin</strong><br>Username: <code>Admin@123</code><br>Password: <code>Admin@123#</code><br><span>${isSupabaseConfigured?'Supabase configured':'Local demo mode — no database setup required yet'}</span></div>
      <div class="login-foot">Passwords are not displayed after creation in production. Super Admin uses secure reset/support access.</div>
    </form></section>
  </div>`;
  $('#login-form').addEventListener('submit', async e=>{
    e.preventDefault(); const username=$('#login-user').value.trim(), password=$('#login-pass').value;
    if (window.HARDWARE_ERP_CONFIG.demoMode || !isSupabaseConfigured) {
      const user=state.users.find(u=>u.username.toLowerCase()===username.toLowerCase() && u.password===password && u.status==='active');
      if(!user) return toast('Sign in failed','Check username, password or account status.','error');
      state.session={userId:user.id,loginAt:new Date().toISOString(),mode:'demo'}; user.lastLogin=new Date().toISOString();
      if(user.tenantId!=='*') state.currentTenantId=user.tenantId;
      state.auditLogs.unshift({id:`AL-${Date.now()}`,tenantId:tenantId(),at:new Date().toISOString(),user:user.displayName,action:'LOGIN',entity:'Session',detail:'Signed in'}); persist();
    } else {
      const {error}=await supabaseLogin(username,password); if(error) return toast('Sign in failed',error.message,'error');
      try {
        state = await loadSupabaseWorkspace(state);
        saveState(state);
        toast('Supabase connected','Workspace loaded from the cloud database.');
        renderApp();
      } catch (err) {
        await supabaseLogout();
        toast('Workspace load failed',err.message,'error');
      }
    }
  });
}

function renderShell() {
  const user=me(), activeShop=shop(); const p=pageInfo[route] || pageInfo.dashboard;
  const nav = navGroups.map(([label,items])=>{
    const filtered=items.filter(([id])=> id==='shops' ? user.role==='super_admin' : (id==='settings'||can(id))); if(!filtered.length) return '';
    return `<div class="nav-label">${label}</div>${filtered.map(([id,icon,name])=>`<button class="nav-item ${route===id?'active':''}" data-route="${id}"><span class="nav-icon">${icon}</span><span>${name}</span>${id==='inventory'&&tenantData('products').filter(x=>x.stock<=x.reorder).length?`<span class="nav-badge">${tenantData('products').filter(x=>x.stock<=x.reorder).length}</span>`:''}</button>`).join('')}`;
  }).join('');
  $('#app').innerHTML=`<div class="app-shell">
    <aside class="sidebar ${ui.mobileNav?'open':''}" id="sidebar">
      <div class="brand-wrap"><div class="brand-mark">HE</div><div><div class="brand-title">Hardware ERP</div><div class="brand-sub">Control Center</div></div></div>
      <div class="tenant-pill"><i class="tenant-dot"></i><div style="min-width:0"><strong>${esc(activeShop.name)}</strong><span>${user.role==='super_admin'?'Super Admin workspace':esc(activeShop.code+' • '+user.branch)}</span></div></div>
      <nav class="nav">${nav}</nav>
      <div class="sidebar-foot"><div class="user-mini" id="profile-menu"><div class="avatar">${initials(user.displayName)}</div><div style="min-width:0;flex:1"><strong>${esc(user.displayName)}</strong><span>${roleLabel(user.role)}</span></div><span>⋯</span></div></div>
    </aside>
    <main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:11px"><button class="icon-btn" id="mobile-menu" style="display:none">☰</button><div class="page-heading"><h1>${p[0]}</h1><p>${p[1]}</p></div></div><div class="top-actions"><div class="searchbox"><span>⌕</span><input id="global-search" placeholder="Search items, customers, invoices…"><kbd style="font-size:8px;color:#607991">⌘ K</kbd></div><button class="icon-btn" id="notification-btn">♢<span class="pulse"></span></button><button class="icon-btn" id="quick-btn">＋</button></div></header><section class="content" id="page"></section></main>
  </div>`;
  renderPage();
  $$('[data-route]').forEach(b=>b.onclick=()=>{route=b.dataset.route;ui.mobileNav=false;renderApp();});
  $('#profile-menu').onclick=()=>openProfileMenu(); $('#notification-btn').onclick=()=>openNotifications(); $('#quick-btn').onclick=()=>openQuickCreate();
  $('#mobile-menu').onclick=()=>{ui.mobileNav=!ui.mobileNav;$('#sidebar').classList.toggle('open',ui.mobileNav)};
  if(innerWidth<=850) $('#mobile-menu').style.display='grid';
  $('#global-search').onkeydown=e=>{if(e.key==='Enter'){ui.productSearch=e.target.value;route='products';renderApp();}};
}

function renderApp() { if(!state.session || !me()) return renderLogin(); renderShell(); }
function renderPage() { const root=$('#page'); root.innerHTML=''; const fn={dashboard:dashboardPage,sales:salesPage,products:productsPage,inventory:inventoryPage,purchasing:purchasingPage,customers:customersPage,suppliers:suppliersPage,delivery:deliveryPage,warranty:warrantyPage,finance:financePage,reports:reportsPage,bulk:bulkPage,users:usersPage,shops:shopsPage,settings:settingsPage}[route]||dashboardPage; root.innerHTML=`<div class="fade-in">${fn()}</div>`; bindPage(); }

function dashboardPage(){
  const products=tenantData('products'), sales=tenantData('sales'), customers=tenantData('customers'), suppliers=tenantData('suppliers');
  const today=new Date().toISOString().slice(0,10), todays=sales.filter(x=>x.date===today); const revenue=todays.reduce((a,b)=>a+b.total,0), cost=todays.reduce((a,b)=>a+b.cost,0), gp=revenue-cost;
  const stockValue=products.reduce((a,b)=>a+b.stock*b.avgCost,0), ar=customers.reduce((a,b)=>a+b.outstanding,0), ap=suppliers.reduce((a,b)=>a+b.payable,0), low=products.filter(x=>x.stock<=x.reorder);
  const week=[6,5,4,3,2,1,0].map(d=>{const date=new Date();date.setDate(date.getDate()-d);const k=date.toISOString().slice(0,10);return sales.filter(s=>s.date===k).reduce((a,b)=>a+b.total,0)}); const max=Math.max(...week,1);
  return `<div class="hero-strip"><div><span class="badge brand">LIVE BUSINESS PULSE</span><h2 style="margin-top:9px">Good to see you, ${esc(me().displayName.split(' ')[0])}.</h2><p>Today’s business health is visible in one place. Low stock, credit exposure and delayed purchasing are surfaced before they become surprises.</p></div><div class="hero-orb"></div></div>
  <div class="grid kpi">
    ${kpi('Today Sales',money(revenue),'↗ 12.4% vs recent day','↗','rgba(32,199,183,.12)')}${kpi('Gross Profit',money(gp),`${percent(gp,revenue)}% gross margin`,'◈','rgba(90,167,255,.12)')}${kpi('Inventory Value',money(stockValue),`${low.length} low-stock item${low.length===1?'':'s'}`,'▦','rgba(155,123,255,.12)')}${kpi('Receivables',money(ar),`${money(ap)} supplier payable`,'◎','rgba(255,189,89,.12)')}
  </div>
  <div class="grid two" style="margin-top:16px"><div class="card pad"><div class="card-head"><div><h3>7-Day Sales Momentum</h3><p>Revenue activity from recent transactions</p></div><span class="badge">LKR</span></div><div class="chart"><div style="height:185px;display:flex;align-items:flex-end;gap:9px;padding:10px 7px 0;border-bottom:1px solid var(--line)">${week.map((v,i)=>`<div style="flex:1;height:${Math.max(8,v/max*100)}%;min-width:20px;border-radius:8px 8px 2px 2px;background:linear-gradient(180deg,rgba(69,230,185,.95),rgba(32,199,183,.18));position:relative;animation:fadeSlide .5s ${i*.04}s both" title="${money(v)}"></div>`).join('')}</div><div style="display:flex;justify-content:space-around;color:var(--muted);font-size:8px;margin-top:10px"><span>6d</span><span>5d</span><span>4d</span><span>3d</span><span>2d</span><span>Yesterday</span><span>Today</span></div></div></div>
  <div class="card pad"><div class="card-head"><div><h3>Action Center</h3><p>Items requiring management attention</p></div><button class="btn small ghost" data-route-jump="inventory">View all</button></div><div class="mini-list">${low.slice(0,4).map(p=>`<div class="mini-item"><div><strong>${esc(p.name)}</strong><span>${p.sku} • ${p.rack}</span></div><div style="text-align:right"><strong style="color:${p.stock<p.reorder*.5?'var(--danger)':'var(--amber)'}">${num(p.stock,2)} ${p.baseUom}</strong><span>Reorder ${num(p.reorder)}</span></div></div>`).join('')}${low.length===0?'<div class="empty"><strong>Everything looks healthy</strong></div>':''}</div></div></div>
  <div class="grid two" style="margin-top:16px"><div class="card pad"><div class="card-head"><div><h3>Quick Actions</h3><p>High-frequency workflows, one click away</p></div></div><div class="quick-actions">${quick('▣','New POS Sale','Open a fast sales counter','sales')}${quick('＋','Add Product','Create SKU, price & UOM','products','add-product')}${quick('⇩','Stock Adjust','Controlled ledger adjustment','inventory','stock-adjust')}${quick('↥','Bulk Update','Paste directly from Excel','bulk')}</div></div><div class="card pad"><div class="card-head"><div><h3>Recent Transactions</h3><p>Latest invoices and payment status</p></div></div><div class="mini-list">${sales.slice(0,4).map(s=>`<div class="mini-item"><div><strong>${s.id}</strong><span>${esc(s.customer)} • ${s.payment}</span></div><div style="text-align:right"><div class="amount">${money(s.total)}</div>${status(s.status)}</div></div>`).join('')}</div></div></div>`;
}
function kpi(label,value,foot,icon,glow){return `<div class="card kpi-card" style="--glow:${glow}"><div class="kpi-top"><span class="kpi-label">${label}</span><div class="kpi-icon">${icon}</div></div><div class="kpi-value">${value}</div><div class="kpi-foot"><span class="delta">●</span>${foot}</div></div>`}
function quick(icon,title,sub,to,action=''){return `<div class="quick" data-quick-route="${to}" ${action?`data-action="${action}"`:''}><div class="q-icon">${icon}</div><strong>${title}</strong><span>${sub}</span></div>`}

function productsPage(){const all=tenantData('products');const cats=['all',...new Set(all.map(x=>x.category))];const q=ui.productSearch.toLowerCase();const rows=all.filter(p=>(ui.productCategory==='all'||p.category===ui.productCategory)&&(!q||[p.sku,p.barcode,p.name,p.brand].join(' ').toLowerCase().includes(q)));
return `<div class="toolbar"><div class="toolbar-left"><div class="searchbox" style="min-width:280px"><span>⌕</span><input id="product-search" placeholder="Search SKU, barcode, product or brand" value="${esc(ui.productSearch)}"></div><select id="product-category" class="filter">${cats.map(c=>`<option ${ui.productCategory===c?'selected':''} value="${esc(c)}">${c==='all'?'All Categories':esc(c)}</option>`).join('')}</select></div><div class="toolbar-right"><button class="btn" data-route-jump="bulk">↥ Bulk Update</button><button class="btn primary" id="add-product">＋ Add Product</button></div></div>
<div class="grid kpi" style="margin-bottom:16px">${kpi('Active SKUs',num(all.length),'Product master','◇','rgba(32,199,183,.1)')}${kpi('Low Stock',num(all.filter(p=>p.stock<=p.reorder).length),'Needs reorder','!','rgba(255,107,122,.1)')}${kpi('Reserved Stock',num(all.reduce((a,b)=>a+b.reserved,0),2),'Against open orders','▣','rgba(90,167,255,.1)')}${kpi('Stock Value',money(all.reduce((a,b)=>a+b.stock*b.avgCost,0)),'At average cost','◈','rgba(155,123,255,.1)')}</div>
<div class="table-wrap"><table><thead><tr><th>Product</th><th>Category / Brand</th><th>UOM</th><th>Available</th><th>Pricing</th><th>Location</th><th>Control</th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="cell-main">${esc(p.name)}</div><div class="cell-sub">${p.sku} • ${p.barcode||'No barcode'}</div></td><td><div>${esc(p.category)}</div><div class="cell-sub">${esc(p.brand)}</div></td><td><span class="badge">${p.baseUom}</span>${p.purchaseUom!==p.baseUom?` <span class="cell-sub">1 ${p.purchaseUom}=${p.conversion} ${p.baseUom}</span>`:''}</td><td><span class="stock-num" style="color:${p.stock<=p.reorder?'var(--danger)':'inherit'}">${num(p.stock,2)}</span><div class="cell-sub">Reserved ${num(p.reserved,2)} • Reorder ${num(p.reorder)}</div></td><td><div class="cell-main">${money(p.retail)}</div><div class="cell-sub">Cost ${money(p.avgCost)} • GP ${percent(p.retail-p.avgCost,p.retail)}%</div></td><td>${esc(p.warehouse)}<div class="cell-sub">Rack ${esc(p.rack)}</div></td><td><button class="btn small" data-edit-product="${p.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`}

function salesPage(){const products=tenantData('products').filter(x=>x.status==='active');const q=ui.posSearch.toLowerCase();const filtered=products.filter(p=>!q||[p.name,p.sku,p.barcode].join(' ').toLowerCase().includes(q));const cart=ui.cart;const subtotal=cart.reduce((a,x)=>a+x.qty*x.price,0); const cost=cart.reduce((a,x)=>a+x.qty*x.avgCost,0);
return `<div class="pos-layout"><div><div class="toolbar"><div class="searchbox" style="min-width:min(520px,100%);flex:1"><span>⌕</span><input id="pos-search" autofocus placeholder="Scan barcode or search item…" value="${esc(ui.posSearch)}"></div><button class="btn" id="hold-sale">Hold</button><button class="btn" data-view-sales-history>History</button></div><div class="product-grid">${filtered.slice(0,24).map(p=>`<div class="product-tile" data-pos-add="${p.id}"><div class="product-avatar">${esc(p.category.slice(0,2).toUpperCase())}</div><strong>${esc(p.name)}</strong><div class="price">${money(p.retail)}</div><div class="stock">${num(p.stock,2)} ${p.baseUom} available • ${p.rack}</div></div>`).join('')}</div></div>
<div class="card pad cart"><div class="card-head"><div><h3>Current Sale</h3><p>${cart.length} line${cart.length===1?'':'s'} • Counter POS</p></div><button class="btn small danger" id="clear-cart">Clear</button></div><div class="field" style="margin-bottom:10px"><label>CUSTOMER</label><select class="input" id="pos-customer">${tenantData('customers').map(c=>`<option value="${c.id}" ${ui.selectedCustomer===c.id?'selected':''}>${esc(c.name)}${c.outstanding?` • Due ${money(c.outstanding)}`:''}</option>`).join('')}</select></div><div>${cart.length?cart.map(x=>`<div class="cart-line"><div><div class="cell-main">${esc(x.name)}</div><div class="cell-sub">${x.sku} • ${money(x.price)}/${x.baseUom}</div></div><div class="qtybox"><button data-cart-minus="${x.id}">−</button><span>${num(x.qty,2)}</span><button data-cart-plus="${x.id}">+</button></div><div style="text-align:right;font-weight:800;font-size:10px">${money(x.qty*x.price)}</div><button class="close-btn" style="width:26px;height:26px" data-cart-remove="${x.id}">×</button></div>`).join(''):`<div class="empty"><div class="empty-icon">▣</div><strong>Your cart is ready</strong><p>Scan a barcode or select an item to begin.</p></div>`}</div><div class="total-panel"><div class="total-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="total-row"><span>Estimated gross profit</span><strong style="color:var(--success)">${money(subtotal-cost)}</strong></div><div class="total-row grand"><span>Total</span><span>${money(subtotal)}</span></div><button class="btn primary" id="checkout" style="width:100%;height:45px;margin-top:10px" ${cart.length?'':'disabled'}>Complete Sale →</button></div></div></div>`}

function inventoryPage(){const p=tenantData('products'), moves=tenantData('stockMovements');const low=p.filter(x=>x.stock<=x.reorder);return `<div class="toolbar"><div class="toolbar-left"><button class="btn primary" id="stock-adjust">＋ Stock Adjustment</button><button class="btn" id="stock-count">▦ Start Stock Count</button><button class="btn" data-route-jump="bulk">↥ Bulk Adjustment</button></div></div><div class="grid kpi" style="margin-bottom:16px">${kpi('On-hand Value',money(p.reduce((a,b)=>a+b.stock*b.avgCost,0)),'Weighted cost basis','▦','rgba(32,199,183,.1)')}${kpi('Low Stock',low.length,'Action required','!','rgba(255,107,122,.1)')}${kpi('Reserved Units',num(p.reduce((a,b)=>a+b.reserved,0),2),'Open order allocation','▣','rgba(90,167,255,.1)')}${kpi('Movements',moves.length,'Auditable transactions','⇄','rgba(155,123,255,.1)')}</div><div class="grid two"><div class="card pad"><div class="card-head"><div><h3>Stock Position</h3><p>Physical, reserved and available quantities</p></div></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Physical</th><th>Reserved</th><th>Available</th><th>Reorder</th></tr></thead><tbody>${p.map(x=>`<tr><td><div class="cell-main">${esc(x.name)}</div><div class="cell-sub">${x.sku} • ${x.rack}</div></td><td>${num(x.stock,2)} ${x.baseUom}</td><td>${num(x.reserved,2)}</td><td><strong>${num(x.stock-x.reserved,2)}</strong></td><td>${x.stock<=x.reorder?status('Low'):status('Healthy')}</td></tr>`).join('')}</tbody></table></div></div><div class="card pad"><div class="card-head"><div><h3>Recent Stock Ledger</h3><p>Immutable movement history</p></div></div><div class="mini-list">${moves.slice(0,8).map(m=>`<div class="mini-item"><div><strong>${esc(m.sku)}</strong><span>${m.type} • ${m.ref} • ${fmtDate(m.date)}</span></div><strong style="color:${m.qty>=0?'var(--success)':'var(--danger)'}">${m.qty>=0?'+':''}${num(m.qty,2)}</strong></div>`).join('')}</div></div></div>`}

function purchasingPage(){const pos=tenantData('purchaseOrders'), suppliers=tenantData('suppliers');return `<div class="toolbar"><div></div><div class="toolbar-right"><button class="btn" id="new-grn">⇩ Receive GRN</button><button class="btn primary" id="new-po">＋ New Purchase Order</button></div></div><div class="grid kpi" style="margin-bottom:16px">${kpi('Open POs',pos.filter(x=>!['received','cancelled'].includes(x.status)).length,'Purchase commitments','⇄','rgba(32,199,183,.1)')}${kpi('Committed Value',money(pos.reduce((a,b)=>a+b.total,0)),'Open purchase value','◈','rgba(90,167,255,.1)')}${kpi('Supplier Payable',money(suppliers.reduce((a,b)=>a+b.payable,0)),'Accounts payable','◎','rgba(255,189,89,.1)')}${kpi('Overdue POs',pos.filter(x=>x.status==='overdue').length,'Follow up supplier','!','rgba(255,107,122,.1)')}</div><div class="table-wrap"><table><thead><tr><th>PO</th><th>Supplier</th><th>Order Date</th><th>Expected</th><th>Items</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${pos.map(x=>`<tr><td class="cell-main">${x.id}</td><td>${esc(x.supplier)}</td><td>${fmtDate(x.date)}</td><td>${fmtDate(x.expected)}</td><td>${x.items}</td><td class="cell-main">${money(x.total)}</td><td>${status(x.status)}</td><td><button class="btn small">View</button></td></tr>`).join('')}</tbody></table></div>`}

function customersPage(){const rows=tenantData('customers');return entityPage('Customers','Contractors, dealers, credit limits and outstanding balances.',rows,[['Customer','name'],['Type','type'],['Phone','phone'],['Credit Limit','creditLimit','money'],['Outstanding','outstanding','money'],['Price Group','priceGroup']], 'add-customer','＋ Add Customer', `<div class="grid kpi" style="margin-bottom:16px">${kpi('Customers',rows.length,'Active accounts','◎','rgba(32,199,183,.1)')}${kpi('Outstanding',money(rows.reduce((a,b)=>a+b.outstanding,0)),'Accounts receivable','◈','rgba(255,189,89,.1)')}${kpi('Credit Exposure',money(rows.reduce((a,b)=>a+b.creditLimit,0)),'Approved limits','▣','rgba(90,167,255,.1)')}${kpi('Over Limit',rows.filter(x=>x.creditLimit&&x.outstanding>x.creditLimit).length,'Requires approval','!','rgba(255,107,122,.1)')}</div>`)}
function suppliersPage(){const rows=tenantData('suppliers');return entityPage('Suppliers','Purchase terms, payables and supply history.',rows,[['Supplier','name'],['Contact','contact'],['Phone','phone'],['Credit Days','terms'],['Payable','payable','money'],['Last Purchase','lastPurchase','date']], 'add-supplier','＋ Add Supplier', `<div class="grid kpi" style="margin-bottom:16px">${kpi('Suppliers',rows.length,'Active partners','◉','rgba(32,199,183,.1)')}${kpi('Payable',money(rows.reduce((a,b)=>a+b.payable,0)),'Outstanding AP','◈','rgba(255,189,89,.1)')}${kpi('Avg Terms',Math.round(rows.reduce((a,b)=>a+b.terms,0)/Math.max(rows.length,1))+' days','Supplier credit','⌁','rgba(90,167,255,.1)')}${kpi('Purchases Due',tenantData('purchaseOrders').filter(x=>x.status==='overdue').length,'Delayed POs','!','rgba(255,107,122,.1)')}</div>`)}
function entityPage(title,sub,rows,cols,addId,addLabel,prefix=''){return `${prefix}<div class="toolbar"><div><span class="badge">${rows.length} RECORDS</span></div><button class="btn primary" id="${addId}">${addLabel}</button></div><div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c[0]}</th>`).join('')}<th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${c[2]==='money'?`<span class="cell-main">${money(r[c[1]])}</span>`:c[2]==='date'?fmtDate(r[c[1]]):`<span class="${c[1]==='name'?'cell-main':''}">${esc(r[c[1]]??'—')}</span>`}</td>`).join('')}<td>${status(r.status||'active')}</td><td><button class="btn small">View</button></td></tr>`).join('')}</tbody></table></div>`}

function deliveryPage(){const rows=tenantData('deliveries');return `<div class="toolbar"><span class="badge">TODAY'S DISPATCH BOARD</span><button class="btn primary" id="new-delivery">＋ Create Delivery</button></div><div class="grid three">${rows.map(d=>`<div class="card pad"><div class="card-head"><div><h3>${d.id}</h3><p>${fmtDate(d.date)}</p></div>${status(d.status)}</div><div class="mini-list"><div class="mini-item"><div><span>Customer</span><strong>${esc(d.customer)}</strong></div></div><div class="mini-item"><div><span>Delivery Site</span><strong>${esc(d.site)}</strong></div></div><div class="mini-item"><div><span>Vehicle / Driver</span><strong>${esc(d.vehicle)} • ${esc(d.driver)}</strong></div><strong>${d.packages} pkg</strong></div></div><div class="action-row" style="margin-top:12px"><button class="btn small">Pick List</button><button class="btn small">POD</button><button class="btn small primary">Update</button></div></div>`).join('')}</div>`}
function warrantyPage(){const rows=tenantData('warrantyClaims');return `<div class="toolbar"><span class="badge">SERIAL-CONTROLLED CLAIMS</span><button class="btn primary" id="new-warranty">＋ New Claim</button></div><div class="table-wrap"><table><thead><tr><th>Claim</th><th>Serial</th><th>Product</th><th>Customer</th><th>Received</th><th>Status</th><th>Note</th></tr></thead><tbody>${rows.map(w=>`<tr><td class="cell-main">${w.id}</td><td><span class="badge">${w.serial}</span></td><td>${esc(w.product)}</td><td>${esc(w.customer)}</td><td>${fmtDate(w.received)}</td><td>${status(w.status)}</td><td>${esc(w.note)}</td></tr>`).join('')}</tbody></table></div>`}
function financePage(){const c=tenantData('customers'),s=tenantData('suppliers'),e=tenantData('expenses'); const ar=c.reduce((a,b)=>a+b.outstanding,0),ap=s.reduce((a,b)=>a+b.payable,0);return `<div class="grid kpi" style="margin-bottom:16px">${kpi('Accounts Receivable',money(ar),'Customer outstanding','◎','rgba(32,199,183,.1)')}${kpi('Accounts Payable',money(ap),'Supplier outstanding','◉','rgba(255,189,89,.1)')}${kpi('Recent Expenses',money(e.reduce((a,b)=>a+b.amount,0)),'Tracked operating costs','−','rgba(255,107,122,.1)')}${kpi('Working Balance',money(ar-ap),'AR less AP','◈','rgba(90,167,255,.1)')}</div><div class="grid two"><div class="card pad"><div class="card-head"><div><h3>Customer Receivables</h3><p>Credit exposure requiring collection</p></div><button class="btn small">Record Receipt</button></div><div class="mini-list">${c.filter(x=>x.outstanding>0).map(x=>`<div class="mini-item"><div><strong>${esc(x.name)}</strong><span>Limit ${money(x.creditLimit)} • ${x.creditDays} days</span></div><div class="amount">${money(x.outstanding)}</div></div>`).join('')}</div></div><div class="card pad"><div class="card-head"><div><h3>Expenses</h3><p>Petty cash and operating spend</p></div><button class="btn small primary" id="add-expense">＋ Expense</button></div><div class="mini-list">${e.map(x=>`<div class="mini-item"><div><strong>${esc(x.description)}</strong><span>${x.category} • ${fmtDate(x.date)}</span></div><div style="text-align:right"><div class="amount">${money(x.amount)}</div>${status(x.status)}</div></div>`).join('')}</div></div></div>`}
function reportsPage(){const p=tenantData('products'),s=tenantData('sales'),c=tenantData('customers');const rev=s.reduce((a,b)=>a+b.total,0),cost=s.reduce((a,b)=>a+b.cost,0);const cats=[...new Set(p.map(x=>x.category))].map(cat=>({cat,value:p.filter(x=>x.category===cat).reduce((a,b)=>a+b.stock*b.avgCost,0)})).sort((a,b)=>b.value-a.value);const max=Math.max(...cats.map(x=>x.value),1);return `<div class="grid kpi" style="margin-bottom:16px">${kpi('Recorded Sales',money(rev),'Transaction dataset','↗','rgba(32,199,183,.1)')}${kpi('Gross Profit',money(rev-cost),`${percent(rev-cost,rev)}% margin`,'◈','rgba(90,167,255,.1)')}${kpi('Stock Value',money(p.reduce((a,b)=>a+b.stock*b.avgCost,0)),'Average cost','▦','rgba(155,123,255,.1)')}${kpi('Outstanding',money(c.reduce((a,b)=>a+b.outstanding,0)),'Customer receivables','◎','rgba(255,189,89,.1)')}</div><div class="grid two"><div class="card pad"><div class="card-head"><div><h3>Inventory by Category</h3><p>Capital distribution across stock</p></div><button class="btn small">Export</button></div>${cats.map(x=>`<div style="margin:13px 0"><div style="display:flex;justify-content:space-between;font-size:9px;margin-bottom:6px"><strong>${esc(x.cat)}</strong><span>${money(x.value)}</span></div><div class="progress"><i style="width:${x.value/max*100}%"></i></div></div>`).join('')}</div><div class="card pad"><div class="card-head"><div><h3>Management Report Library</h3><p>Ready-to-run operational reports</p></div></div><div class="quick-actions">${quick('↗','Sales & GP','Daily/monthly sales and margin','reports')}${quick('▦','Stock Aging','Fast/slow/dead stock','reports')}${quick('◎','Credit Aging','Current, 30, 60, 90+','reports')}${quick('⇄','Purchasing','PO, GRN and cost variance','reports')}</div></div></div>`}

function bulkPage(){const def=bulkDefinitions[ui.bulkType], rows=ui.bulkRows, valid=rows.filter(x=>x.__valid).length, bad=rows.length-valid;return `<div class="hero-strip" style="min-height:100px"><div><span class="badge brand">SAFE BULK OPERATIONS</span><h2 style="margin-top:9px">Excel-speed data entry without losing control.</h2><p>Download the exact template, fill it in Excel, copy the rows and paste here. The system maps columns, validates references and shows a change preview before anything is committed.</p></div><div class="hero-orb"></div></div><div class="bulk-steps">${['Choose operation','Download template','Fill in Excel','Paste / upload','Validate & review','Apply changes'].map((x,i)=>`<div class="step ${i<= (rows.length?4:2)?'active':''}"><b>${i+1}</b>${x}</div>`).join('')}</div><div class="grid two"><div class="card pad"><div class="field"><label>WHAT DO YOU WANT TO UPDATE?</label><select class="input" id="bulk-type">${Object.entries(bulkDefinitions).map(([k,v])=>`<option value="${k}" ${ui.bulkType===k?'selected':''}>${v.label}</option>`).join('')}</select></div><div class="action-row" style="margin:12px 0"><button class="btn blue" id="download-template">↓ Download Excel Template</button><label class="btn" for="bulk-file">↥ Upload Excel<input id="bulk-file" type="file" accept=".xlsx,.xls,.csv,.tsv,.txt" hidden></label></div><div class="bulk-drop"><div class="field"><label>PASTE FROM EXCEL</label><textarea class="textarea" id="bulk-text" placeholder="Copy rows in Excel (Ctrl+C), then paste here (Ctrl+V)…">${esc(ui.bulkText)}</textarea><small>Expected columns: ${def.columns.join(' • ')}</small></div><div class="action-row" style="margin-top:10px"><button class="btn primary" id="validate-bulk">Validate Data →</button><button class="btn" id="clear-bulk">Clear</button></div></div></div><div class="card pad"><div class="card-head"><div><h3>Validation Preview</h3><p>No database changes happen until you confirm.</p></div></div>${rows.length?`<div class="validation-summary"><span class="summary-pill">${rows.length} rows</span><span class="summary-pill good">✓ ${valid} valid</span><span class="summary-pill bad">× ${bad} blocked</span></div><div class="table-wrap" style="max-height:360px"><table><thead><tr><th>Row</th><th>Key</th><th>Result</th><th>Message</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.__row}</td><td class="cell-main">${esc(r[def.key]||'—')}</td><td>${r.__valid?status('Valid'):status('Failed')}</td><td>${r.__errors.length?`<span style="color:var(--danger)">${esc(r.__errors.join('; '))}</span>`:r.__warnings.length?`<span style="color:var(--amber)">${esc(r.__warnings.join('; '))}</span>`:'Ready to import'}</td></tr>`).join('')}</tbody></table></div><button class="btn primary" id="apply-bulk" style="width:100%;margin-top:12px" ${valid?'':'disabled'}>Apply ${valid} Valid Row${valid===1?'':'s'} →</button>`:`<div class="empty"><div class="empty-icon">↥</div><strong>Waiting for spreadsheet data</strong><p>Use the system template to guarantee perfect field recognition.</p></div>`}</div></div>`}

function usersPage(){const user=me();const rows=state.users.filter(u=>user.role==='super_admin' ? (u.tenantId===tenantId()||u.tenantId==='*') : u.tenantId===tenantId());return `<div class="toolbar"><div><span class="badge">${rows.length} ACCOUNTS</span> <span class="badge">PASSWORDS HIDDEN BY DESIGN</span></div><button class="btn primary" id="add-user">＋ Add User</button></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Username</th><th>Role</th><th>Branch</th><th>Last Login</th><th>Status</th><th>Controls</th></tr></thead><tbody>${rows.map(u=>`<tr><td><div style="display:flex;align-items:center;gap:9px"><div class="avatar" style="width:30px;height:30px;border-radius:9px">${initials(u.displayName)}</div><div><div class="cell-main">${esc(u.displayName)}</div><div class="cell-sub">${u.tempPassword?'Must change password':'Password protected'}</div></div></div></td><td><span class="badge">${esc(u.username)}</span></td><td>${roleLabel(u.role)}</td><td>${esc(u.branch)}</td><td>${fmtDate(u.lastLogin)}</td><td>${status(u.status)}</td><td><div class="action-row"><button class="btn small" data-user-edit="${u.id}">Edit</button>${u.id!==user.id?`<button class="btn small" data-user-reset="${u.id}">Reset Password</button>`:''}${user.role==='super_admin'&&u.id!==user.id?`<button class="btn small" data-support-user="${u.id}">Support View</button>`:''}</div></td></tr>`).join('')}</tbody></table></div><div class="card pad" style="margin-top:16px"><div class="card-head"><div><h3>Security Model</h3><p>Super Admin retains control without storing readable passwords.</p></div></div><div class="quick-actions">${quick('♙','Create Accounts','Shop admins create their own staff','users')}${quick('↻','Secure Reset','Set a temporary password','users')}${quick('◉','Support View','Audited impersonation-style support','users')}${quick('⌁','Audit Trail','Every sensitive action is logged','users')}</div></div>`}

function shopsPage(){if(me().role!=='super_admin') return `<div class="empty"><strong>Super Admin only</strong></div>`;return `<div class="toolbar"><div><span class="badge">${state.shops.length} TENANTS</span></div><button class="btn primary" id="add-shop">＋ Add Shop</button></div><div class="grid three">${state.shops.map(s=>{const users=state.users.filter(u=>u.tenantId===s.id).length,p=state.products.filter(x=>x.tenantId===s.id).length;return `<div class="card pad"><div class="card-head"><div style="display:flex;gap:10px;align-items:center"><div class="avatar">${esc(s.logo)}</div><div><h3>${esc(s.name)}</h3><p>${esc(s.code)} • ${esc(s.plan)}</p></div></div>${status(s.status)}</div><div class="mini-list"><div class="mini-item"><span>Users</span><strong>${users}</strong></div><div class="mini-item"><span>Products</span><strong>${p}</strong></div><div class="mini-item"><span>Contact</span><strong>${esc(s.phone)}</strong></div></div><div class="action-row" style="margin-top:12px"><button class="btn small primary" data-enter-shop="${s.id}">Open Workspace</button><button class="btn small">Manage</button></div></div>`}).join('')}</div>`}

function settingsPage(){const st=state.settings[tenantId()]||{vatRate:18,ssclRate:2.5,taxRegistered:false,negativeStock:false,discountApproval:10};return `<div class="grid equal-two"><div class="card pad"><div class="card-head"><div><h3>Business Profile</h3><p>Identity used on documents and reports</p></div></div><div class="form-grid"><div class="field span-2"><label>BUSINESS NAME</label><input class="input" value="${esc(shop().name)}" disabled></div><div class="field"><label>BUSINESS CODE</label><input class="input" value="${esc(shop().code)}" disabled></div><div class="field"><label>PHONE</label><input class="input" value="${esc(shop().phone)}"></div><div class="field span-2"><label>ADDRESS</label><input class="input" value="${esc(shop().address)}"></div></div></div><div class="card pad"><div class="card-head"><div><h3>Tax & Control</h3><p>Configurable — never hard-code statutory rates</p></div></div><div class="form-grid"><div class="field"><label>VAT RATE %</label><input class="input" type="number" value="${st.vatRate}"></div><div class="field"><label>SSCL RATE %</label><input class="input" type="number" value="${st.ssclRate}"></div><div class="permission span-2"><span>VAT Registered</span><div class="toggle ${st.taxRegistered?'on':''}"><i></i></div></div><div class="permission span-2"><span>Allow Negative Stock</span><div class="toggle ${st.negativeStock?'on':''}"><i></i></div></div></div></div><div class="card pad"><div class="card-head"><div><h3>Database Connection</h3><p>Supabase / local demo status</p></div>${status(isSupabaseConfigured?'Connected':'Demo')}</div><div class="mini-list"><div class="mini-item"><div><strong>Frontend</strong><span>Static web app • GitHub Pages compatible</span></div><span class="badge">Ready</span></div><div class="mini-item"><div><strong>Supabase</strong><span>${isSupabaseConfigured?'Project URL and publishable key configured':'Edit config.js after running schema.sql'}</span></div><span class="badge">${isSupabaseConfigured?'Configured':'Pending'}</span></div><div class="mini-item"><div><strong>RLS Security</strong><span>Enable with supplied schema before production</span></div><span class="badge">Required</span></div></div></div><div class="card pad"><div class="card-head"><div><h3>Demo Maintenance</h3><p>Local browser data tools</p></div></div><div class="action-row"><button class="btn" id="export-json">↓ Export Demo Data</button><button class="btn danger" id="reset-demo">Reset Demo Database</button></div></div></div>`}

function bindPage(){
  $$('[data-route-jump]').forEach(b=>b.onclick=()=>{route=b.dataset.routeJump;renderApp()});
  $$('[data-quick-route]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;route=b.dataset.quickRoute;renderApp();setTimeout(()=>{if(a==='add-product')openProduct();if(a==='stock-adjust')openStockAdjustment()},0)});
  if(route==='products') bindProducts(); if(route==='sales') bindSales(); if(route==='inventory') bindInventory(); if(route==='bulk') bindBulk(); if(route==='users') bindUsers(); if(route==='shops') bindShops();
  $('#add-customer')?.addEventListener('click',()=>openEntity('customer')); $('#add-supplier')?.addEventListener('click',()=>openEntity('supplier')); $('#add-expense')?.addEventListener('click',openExpense);
  $('#new-po')?.addEventListener('click',openPO); $('#new-grn')?.addEventListener('click',()=>toast('GRN workflow','Use PO → Receive to create auditable stock movements.'));
  $('#new-delivery')?.addEventListener('click',()=>toast('Delivery workflow','Delivery creation UI is included as a workflow scaffold in this starter.'));
  $('#new-warranty')?.addEventListener('click',()=>toast('Warranty workflow','Create claims against serial-controlled items in the Supabase-backed phase.'));
  $('#export-json')?.addEventListener('click',exportJSON); $('#reset-demo')?.addEventListener('click',()=>{if(confirm('Reset all demo data?')){state=resetDemo();state.session=null;renderApp();}});
}

function bindProducts(){ $('#product-search').oninput=e=>{ui.productSearch=e.target.value;renderPage()}; $('#product-category').onchange=e=>{ui.productCategory=e.target.value;renderPage()}; $('#add-product').onclick=()=>openProduct(); $$('[data-edit-product]').forEach(b=>b.onclick=()=>openProduct(b.dataset.editProduct)); }
function openProduct(id){const p=id?state.products.find(x=>x.id===id):null;const body=`<form id="product-form" class="form-grid"><div class="field"><label>SKU *</label><input class="input" name="sku" required value="${esc(p?.sku||'')}"></div><div class="field"><label>BARCODE</label><input class="input" name="barcode" value="${esc(p?.barcode||'')}"></div><div class="field span-2"><label>ITEM NAME *</label><input class="input" name="name" required value="${esc(p?.name||'')}"></div><div class="field"><label>CATEGORY</label><input class="input" name="category" value="${esc(p?.category||'General')}"></div><div class="field"><label>BRAND</label><input class="input" name="brand" value="${esc(p?.brand||'')}"></div><div class="field"><label>BASE UOM</label><select class="input" name="baseUom">${['PCS','BOX','M','FT','KG','G','L','ML','BAG','ROLL','LEN','TIN','PAIR'].map(x=>`<option ${p?.baseUom===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>PURCHASE UOM</label><input class="input" name="purchaseUom" value="${esc(p?.purchaseUom||'PCS')}"></div><div class="field"><label>UOM CONVERSION</label><input class="input" type="number" step="0.001" name="conversion" value="${p?.conversion||1}"></div><div class="field"><label>AVERAGE COST</label><input class="input" type="number" step="0.01" name="avgCost" value="${p?.avgCost||0}"></div><div class="field"><label>RETAIL PRICE</label><input class="input" type="number" step="0.01" name="retail" value="${p?.retail||0}"></div><div class="field"><label>MINIMUM PRICE</label><input class="input" type="number" step="0.01" name="minPrice" value="${p?.minPrice||0}"></div><div class="field"><label>OPENING / CURRENT STOCK</label><input class="input" type="number" step="0.001" name="stock" value="${p?.stock||0}" ${p?'readonly':''}></div><div class="field"><label>REORDER LEVEL</label><input class="input" type="number" step="0.001" name="reorder" value="${p?.reorder||0}"></div><div class="field"><label>WAREHOUSE</label><input class="input" name="warehouse" value="${esc(p?.warehouse||'Main Warehouse')}"></div><div class="field"><label>RACK / BIN</label><input class="input" name="rack" value="${esc(p?.rack||'')}"></div></form>`;const m=modal(p?'Edit Product':'Add Product',p?'Update master data and pricing.':'Create a new stock keeping unit.',body,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="save-product">${p?'Save Changes':'Create Product'}</button>`);
$('#save-product',m).onclick=()=>{const f=new FormData($('#product-form',m));const o=Object.fromEntries(f.entries());['conversion','avgCost','retail','minPrice','stock','reorder'].forEach(k=>o[k]=Number(o[k]||0));o.trade=p?.trade||o.retail;o.wholesale=p?.wholesale||o.retail;o.reserved=p?.reserved||0;o.status='active';o.serial=p?.serial||false;o.batch=p?.batch||false;if(!o.sku||!o.name)return toast('Missing fields','SKU and Item Name are required.','error');if(p)Object.assign(p,o);else{const np={id:`p-${Date.now()}`,tenantId:tenantId(),...o};state.products.unshift(np);if(o.stock){state.stockMovements.unshift({id:`SM-${Date.now()}-OPEN`,tenantId:tenantId(),date:new Date().toISOString().slice(0,10),sku:o.sku,type:'Opening Balance',qty:o.stock,ref:`OPEN-${Date.now()}`,user:me().displayName});}}state.auditLogs.unshift({id:`AL-${Date.now()}`,tenantId:tenantId(),at:new Date().toISOString(),user:me().displayName,action:p?'PRODUCT_UPDATE':'PRODUCT_CREATE',entity:o.sku,detail:o.name});persist(false);m.remove();toast(p?'Product updated':'Product created',o.name);renderPage();};}

function bindSales(){ $('#pos-search').oninput=e=>{ui.posSearch=e.target.value;renderPage()}; $$('#page [data-pos-add]').forEach(b=>b.onclick=()=>addToCart(b.dataset.posAdd)); $('#clear-cart').onclick=()=>{ui.cart=[];renderPage()}; $('#pos-customer').onchange=e=>ui.selectedCustomer=e.target.value; $$('#page [data-cart-plus]').forEach(b=>b.onclick=()=>changeCart(b.dataset.cartPlus,1)); $$('#page [data-cart-minus]').forEach(b=>b.onclick=()=>changeCart(b.dataset.cartMinus,-1)); $$('#page [data-cart-remove]').forEach(b=>b.onclick=()=>{ui.cart=ui.cart.filter(x=>x.id!==b.dataset.cartRemove);renderPage()}); $('#checkout').onclick=openCheckout; }
function addToCart(id){const p=state.products.find(x=>x.id===id);let c=ui.cart.find(x=>x.id===id);if(c)c.qty+=1;else ui.cart.push({id:p.id,sku:p.sku,name:p.name,baseUom:p.baseUom,qty:1,price:p.retail,avgCost:p.avgCost});renderPage();}
function changeCart(id,d){const c=ui.cart.find(x=>x.id===id);if(!c)return;c.qty=Math.max(.001,c.qty+d);renderPage();}
function openCheckout(){const total=ui.cart.reduce((a,x)=>a+x.qty*x.price,0);const body=`<div class="grid equal-two"><div class="field"><label>PAYMENT METHOD</label><select class="input" id="pay-method"><option>Cash</option><option>Card</option><option>Bank</option><option>Credit</option><option>QR</option></select></div><div class="field"><label>AMOUNT RECEIVED</label><input class="input" id="paid-amount" type="number" step="0.01" value="${total.toFixed(2)}"></div></div><div class="card pad" style="margin-top:15px"><div class="total-row grand"><span>Invoice Total</span><span>${money(total)}</span></div></div>`;const m=modal('Complete Sale','Post invoice, payment and stock movements as one transaction.',body,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="post-sale">Post Sale</button>`,'small');$('#post-sale',m).onclick=()=>{const customer=state.customers.find(c=>c.id===ui.selectedCustomer),method=$('#pay-method',m).value,cost=ui.cart.reduce((a,x)=>a+x.qty*x.avgCost,0),id=`INV-${new Date().toISOString().slice(2,10).replaceAll('-','')}-${String(state.sales.length+1).padStart(4,'0')}`;for(const c of ui.cart){const p=state.products.find(x=>x.id===c.id);if(p.stock<c.qty && !(state.settings[tenantId()]?.negativeStock))return toast('Insufficient stock',`${p.name} has only ${p.stock} ${p.baseUom}.`,'error');}ui.cart.forEach(c=>{const p=state.products.find(x=>x.id===c.id);p.stock-=c.qty;state.stockMovements.unshift({id:`SM-${Date.now()}-${c.id}`,tenantId:tenantId(),date:new Date().toISOString().slice(0,10),sku:p.sku,type:'Sale',qty:-c.qty,ref:id,user:me().displayName})});state.sales.unshift({id,tenantId:tenantId(),date:new Date().toISOString().slice(0,10),customer:customer?.name||'Walk-in Customer',total,cost,payment:method,status:method==='Credit'?'credit':'paid',user:me().displayName});if(method==='Credit'&&customer)customer.outstanding+=total;state.auditLogs.unshift({id:`AL-${Date.now()}`,tenantId:tenantId(),at:new Date().toISOString(),user:me().displayName,action:'SALE_POSTED',entity:id,detail:`${money(total)} • ${method}`});persist(false);ui.cart=[];m.remove();toast('Sale completed',`${id} • ${money(total)}`);renderPage();};}

function bindInventory(){ $('#stock-adjust').onclick=openStockAdjustment; $('#stock-count').onclick=()=>toast('Blind stock count started','Production version supports counted qty, variance review and approval.'); }
function openStockAdjustment(){const products=tenantData('products');const body=`<div class="form-grid"><div class="field span-2"><label>PRODUCT</label><select class="input" id="adj-product">${products.map(p=>`<option value="${p.id}">${esc(p.sku)} — ${esc(p.name)} (${num(p.stock,2)} ${p.baseUom})</option>`).join('')}</select></div><div class="field"><label>ADJUSTMENT QTY</label><input class="input" id="adj-qty" type="number" step="0.001" placeholder="Use negative to reduce"></div><div class="field"><label>REASON</label><select class="input" id="adj-reason"><option>Count correction</option><option>Damage</option><option>Breakage</option><option>Conversion</option><option>System correction</option></select></div></div>`;const m=modal('Stock Adjustment','Never edits stock silently — creates an auditable movement.',body,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="save-adjust">Post Adjustment</button>`,'small');$('#save-adjust',m).onclick=()=>{const p=state.products.find(x=>x.id===$('#adj-product',m).value),qty=Number($('#adj-qty',m).value),reason=$('#adj-reason',m).value;if(!qty)return toast('Enter a quantity','Adjustment cannot be zero.','error');const before=p.stock;p.stock+=qty;const ref=`ADJ-${Date.now()}`;state.stockMovements.unshift({id:`SM-${Date.now()}`,tenantId:tenantId(),date:new Date().toISOString().slice(0,10),sku:p.sku,type:'Adjustment',qty,ref,user:me().displayName});state.auditLogs.unshift({id:`AL-${Date.now()}`,tenantId:tenantId(),at:new Date().toISOString(),user:me().displayName,action:'STOCK_ADJUST',entity:p.sku,detail:`${before} → ${p.stock}; ${reason}`});persist(false);m.remove();toast('Stock adjusted',`${p.sku}: ${qty>0?'+':''}${qty}`);renderPage();};}

function bindBulk(){ $('#bulk-type').onchange=e=>{ui.bulkType=e.target.value;ui.bulkRows=[];ui.bulkText='';renderPage()}; $('#download-template').onclick=()=>downloadTemplate(ui.bulkType); $('#bulk-text').oninput=e=>ui.bulkText=e.target.value; $('#validate-bulk').onclick=()=>{const parsed=parseClipboard($('#bulk-text').value,bulkDefinitions[ui.bulkType]);ui.bulkText=$('#bulk-text').value;ui.bulkRows=validateRows(parsed.items,ui.bulkType,state,tenantId());renderPage()}; $('#clear-bulk').onclick=()=>{ui.bulkRows=[];ui.bulkText='';renderPage()}; $('#apply-bulk')?.addEventListener('click',()=>{const count=applyRows(ui.bulkRows,ui.bulkType,state,tenantId(),me().displayName);persist(false);ui.bulkRows=[];ui.bulkText='';toast('Bulk update completed',`${count} row(s) safely applied.`);renderPage()}); $('#bulk-file').onchange=handleBulkFile; }
async function handleBulkFile(e){const file=e.target.files[0];if(!file)return;try{const ab=await file.arrayBuffer();if(window.XLSX){const wb=XLSX.read(ab,{type:'array'}),ws=wb.Sheets[wb.SheetNames[0]],arr=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});ui.bulkText=arr.map(r=>r.join('\t')).join('\n');const parsed=parseClipboard(ui.bulkText,bulkDefinitions[ui.bulkType]);ui.bulkRows=validateRows(parsed.items,ui.bulkType,state,tenantId());renderPage();toast('Spreadsheet loaded',`${ui.bulkRows.length} row(s) read from ${file.name}`)}else throw new Error('Excel parser not loaded');}catch(err){toast('Could not read file',err.message,'error')}}

function bindUsers(){ $('#add-user').onclick=openUserCreate; $$('[data-user-reset]').forEach(b=>b.onclick=()=>openPasswordReset(b.dataset.userReset)); $$('[data-support-user]').forEach(b=>b.onclick=()=>supportView(b.dataset.supportUser)); $$('[data-user-edit]').forEach(b=>b.onclick=()=>openUserEdit(b.dataset.userEdit)); }
function openUserCreate(){
  const roles=me().role==='super_admin'?['shop_admin','manager','cashier','sales','stores','accounts','delivery','auditor']:['manager','cashier','sales','stores','accounts','delivery','auditor'];
  const body=`<div class="form-grid"><div class="field span-2"><label>FULL NAME *</label><input class="input" id="u-name"></div><div class="field"><label>USERNAME *</label><input class="input" id="u-user"></div><div class="field"><label>ROLE</label><select class="input" id="u-role">${roles.map(r=>`<option value="${r}">${roleLabel(r)}</option>`).join('')}</select></div><div class="field"><label>BRANCH</label><input class="input" id="u-branch" value="Main Branch"></div><div class="field"><label>TEMPORARY PASSWORD *</label><input class="input" id="u-pass" value="Temp@123#"></div></div><p style="font-size:9px;color:var(--muted);line-height:1.5;margin-top:13px">The temporary password is shown during creation/reset only. Existing passwords are not readable.</p>`;
  const m=modal('Add User','Create a shop account with role-based access.',body,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="create-user">Create Account</button>`,'small');
  $('#create-user',m).onclick=async()=>{
    const name=$('#u-name',m).value.trim(),username=$('#u-user',m).value.trim(),password=$('#u-pass',m).value,role=$('#u-role',m).value,branch=$('#u-branch',m).value;
    if(!name||!username||!password)return toast('Missing fields','Name, username and password are required.','error');
    if(state.users.some(u=>u.username.toLowerCase()===username.toLowerCase()))return toast('Username exists','Choose a different username.','error');
    if(state.session?.mode==='supabase'){
      try{await callAdminUsers('create',{tenantId:tenantId(),username,password,displayName:name,role,branch});state=await loadSupabaseWorkspace(state);saveState(state);m.remove();toast('Account created',`${username} • temporary password configured`);renderPage();}catch(err){toast('Account creation failed',err.message,'error')}return;
    }
    state.users.push({id:`usr-${Date.now()}`,tenantId:tenantId(),username,displayName:name,role,branch,status:'active',lastLogin:null,tempPassword:true,password});
    state.auditLogs.unshift({id:`AL-${Date.now()}`,tenantId:tenantId(),at:new Date().toISOString(),user:me().displayName,action:'USER_CREATE',entity:username,detail:`Role ${roleLabel(role)}`});saveState(state);m.remove();toast('Account created',`${username} • temporary password configured`);renderPage();
  };
}

function openPasswordReset(id){
  const u=state.users.find(x=>x.id===id); const temp=`Reset@${Math.floor(1000+Math.random()*8999)}#`;
  const body=`<div class="field"><label>NEW TEMPORARY PASSWORD</label><input class="input" id="reset-pass" value="${temp}"></div><p style="color:var(--muted);font-size:9px;line-height:1.5">This replaces the current password. The old password remains unrecoverable in the production Supabase model.</p>`;
  const m=modal('Reset Password',`Set a temporary password for ${esc(u.displayName)}.`,body,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="do-reset">Reset Password</button>`,'small');
  $('#do-reset',m).onclick=async()=>{const password=$('#reset-pass',m).value;if(state.session?.mode==='supabase'){try{await callAdminUsers('reset-password',{userId:u.id,password});u.tempPassword=true;m.remove();toast('Password reset','Temporary password is active.');renderPage();}catch(err){toast('Password reset failed',err.message,'error')}return;}u.password=password;u.tempPassword=true;state.auditLogs.unshift({id:`AL-${Date.now()}`,tenantId:tenantId(),at:new Date().toISOString(),user:me().displayName,action:'PASSWORD_RESET',entity:u.username,detail:'Temporary password set'});saveState(state);m.remove();toast('Password reset','Temporary password is active.');renderPage();};
}

function openUserEdit(id){
  const u=state.users.find(x=>x.id===id);
  const body=`<div class="form-grid"><div class="field span-2"><label>DISPLAY NAME</label><input class="input" id="edit-u-name" value="${esc(u.displayName)}"></div><div class="field"><label>ROLE</label><select class="input" id="edit-u-role">${['shop_admin','manager','cashier','sales','stores','accounts','delivery','auditor'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${roleLabel(r)}</option>`).join('')}</select></div><div class="field"><label>STATUS</label><select class="input" id="edit-u-status"><option ${u.status==='active'?'selected':''}>active</option><option ${u.status==='suspended'?'selected':''}>suspended</option></select></div></div>`;
  const m=modal('Edit User','Update account role and status.',body,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="save-user-edit">Save</button>`,'small');
  $('#save-user-edit',m).onclick=async()=>{const displayName=$('#edit-u-name',m).value,role=$('#edit-u-role',m).value,statusValue=$('#edit-u-status',m).value;if(state.session?.mode==='supabase'){try{await callAdminUsers('update-profile',{userId:u.id,displayName,role,status:statusValue});state=await loadSupabaseWorkspace(state);saveState(state);m.remove();toast('User updated');renderPage();}catch(err){toast('User update failed',err.message,'error')}return;}u.displayName=displayName;u.role=role;u.status=statusValue;saveState(state);m.remove();toast('User updated');renderPage();};
}

function supportView(id){const u=state.users.find(x=>x.id===id);if(!u)return;state.supportSession={superAdminId:me().id,targetUserId:u.id,startedAt:new Date().toISOString()};state.auditLogs.unshift({id:`AL-${Date.now()}`,tenantId:u.tenantId,at:new Date().toISOString(),user:me().displayName,action:'SUPPORT_VIEW',entity:u.username,detail:'Audited support access session opened'});toast('Support access logged',`Viewing permissions context for ${u.displayName}.`);persist(false);}

function bindShops(){ $('#add-shop').onclick=openShopCreate; $$('[data-enter-shop]').forEach(b=>b.onclick=async()=>{state.currentTenantId=b.dataset.enterShop;if(state.session?.mode==='supabase'){try{await loadTenantDataIntoState(state,state.currentTenantId)}catch(err){return toast('Could not load shop',err.message,'error')}}saveState(state);route='dashboard';toast('Workspace changed',shop().name);renderApp()}); }
function openShopCreate(){
  const body=`<div class="form-grid"><div class="field span-2"><label>SHOP / BUSINESS NAME *</label><input class="input" id="shop-name"></div><div class="field"><label>CODE</label><input class="input" id="shop-code" placeholder="ABC"></div><div class="field"><label>PHONE</label><input class="input" id="shop-phone"></div><div class="field span-2"><label>ADDRESS</label><input class="input" id="shop-address"></div><div class="field"><label>ADMIN USERNAME *</label><input class="input" id="shop-admin"></div><div class="field"><label>TEMP PASSWORD *</label><input class="input" id="shop-pass" value="Shop@123#"></div></div>`;
  const m=modal('Create New Shop','Creates a tenant and its first Shop Admin account.',body,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="create-shop">Create Shop</button>`);
  $('#create-shop',m).onclick=async()=>{const name=$('#shop-name',m).value.trim(),username=$('#shop-admin',m).value.trim();if(!name||!username)return toast('Missing data','Shop name and admin username are required.','error');const code=$('#shop-code',m).value.trim().toUpperCase()||name.replace(/[^A-Za-z]/g,'').slice(0,3).toUpperCase();const address=$('#shop-address',m).value,phone=$('#shop-phone',m).value,password=$('#shop-pass',m).value;if(state.session?.mode==='supabase'){try{await createSupabaseShop({name,code,address,phone},{username,password,displayName:`${name} Admin`});state=await loadSupabaseWorkspace(state);saveState(state);m.remove();toast('Shop created',`${name} is isolated under tenant ${code}.`);renderPage();}catch(err){toast('Shop creation failed',err.message,'error')}return;}const id=`tenant-${Date.now()}`;state.shops.push({id,name,code,status:'active',plan:'Trial',address,phone,email:'',brn:'',vat:'',logo:initials(name),createdAt:new Date().toISOString()});state.users.push({id:`usr-${Date.now()}`,tenantId:id,username,displayName:`${name} Admin`,role:'shop_admin',branch:'Main Branch',status:'active',lastLogin:null,tempPassword:true,password});state.settings[id]={currency:'LKR',vatRate:18,ssclRate:2.5,taxRegistered:false,negativeStock:false,discountApproval:10};saveState(state);m.remove();toast('Shop created',`${name} is isolated under tenant ${code}.`);renderPage();};
}

function openEntity(kind){const customer=kind==='customer';const body=`<div class="form-grid"><div class="field"><label>${customer?'CUSTOMER':'SUPPLIER'} CODE</label><input class="input" id="e-code" value="${customer?'CUS':'SUP'}-${String((customer?state.customers:state.suppliers).length+1).padStart(4,'0')}"></div><div class="field"><label>${customer?'TYPE':'CREDIT DAYS'}</label>${customer?'<select class="input" id="e-type"><option>Retail</option><option>Contractor</option><option>Dealer</option><option>Wholesale</option></select>':'<input class="input" id="e-terms" type="number" value="30">'}</div><div class="field span-2"><label>NAME *</label><input class="input" id="e-name"></div><div class="field"><label>PHONE</label><input class="input" id="e-phone"></div><div class="field"><label>${customer?'CREDIT LIMIT':'CONTACT PERSON'}</label><input class="input" id="e-extra" ${customer?'type="number" value="0"':''}></div></div>`;const m=modal(`Add ${customer?'Customer':'Supplier'}`,'Create a new master record.',body,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="save-entity">Create</button>`,'small');$('#save-entity',m).onclick=()=>{const name=$('#e-name',m).value.trim();if(!name)return toast('Name required','','error');if(customer)state.customers.push({id:`c-${Date.now()}`,tenantId:tenantId(),code:$('#e-code',m).value,name,type:$('#e-type',m).value,phone:$('#e-phone',m).value,email:'',creditLimit:Number($('#e-extra',m).value||0),creditDays:30,outstanding:0,priceGroup:'Retail',status:'active'});else state.suppliers.push({id:`s-${Date.now()}`,tenantId:tenantId(),code:$('#e-code',m).value,name,phone:$('#e-phone',m).value,contact:$('#e-extra',m).value,terms:Number($('#e-terms',m).value||0),payable:0,lastPurchase:null,status:'active'});persist(false);m.remove();toast(`${customer?'Customer':'Supplier'} created`,name);renderPage();};}
function openExpense(){const body=`<div class="form-grid"><div class="field"><label>CATEGORY</label><select class="input" id="ex-cat"><option>Transport</option><option>Fuel</option><option>Loading</option><option>Repairs</option><option>Electricity</option><option>Stationery</option><option>Other</option></select></div><div class="field"><label>AMOUNT</label><input class="input" id="ex-amount" type="number"></div><div class="field span-2"><label>DESCRIPTION</label><input class="input" id="ex-desc"></div></div>`;const m=modal('Record Expense','Track operating expenses with approval status.',body,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="save-expense">Save Expense</button>`,'small');$('#save-expense',m).onclick=()=>{state.expenses.unshift({id:`EXP-${Date.now()}`,tenantId:tenantId(),date:new Date().toISOString().slice(0,10),category:$('#ex-cat',m).value,description:$('#ex-desc',m).value,amount:Number($('#ex-amount',m).value||0),status:'approved'});persist(false);m.remove();toast('Expense recorded');renderPage()};}
function openPO(){const body=`<div class="form-grid"><div class="field span-2"><label>SUPPLIER</label><select class="input" id="po-sup">${tenantData('suppliers').map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>EXPECTED DATE</label><input class="input" id="po-date" type="date"></div><div class="field"><label>ESTIMATED TOTAL</label><input class="input" id="po-total" type="number"></div><div class="field span-2"><label>ITEM COUNT</label><input class="input" id="po-items" type="number" value="1"></div></div>`;const m=modal('New Purchase Order','Starter PO header — item-line editor is ready to extend.',body,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="save-po">Create PO</button>`,'small');$('#save-po',m).onclick=()=>{state.purchaseOrders.unshift({id:`PO-${new Date().toISOString().slice(2,10).replaceAll('-','')}-${String(state.purchaseOrders.length+1).padStart(4,'0')}`,tenantId:tenantId(),supplier:$('#po-sup',m).value,date:new Date().toISOString().slice(0,10),expected:$('#po-date',m).value,total:Number($('#po-total',m).value||0),status:'approved',items:Number($('#po-items',m).value||1)});persist(false);m.remove();toast('Purchase order created');renderPage()};}

function openNotifications(){const notes=tenantData('notifications');modal('Notifications','Operational alerts generated from business rules.',`<div class="mini-list">${notes.map(n=>`<div class="mini-item"><div><strong>${esc(n.title)}</strong><span>${esc(n.body)}</span></div><span class="status ${n.type==='danger'?'overdue':n.type==='warning'?'pending':'active'}">${n.type}</span></div>`).join('')}</div>`,'','small');}
function openQuickCreate(){modal('Quick Create','Jump directly to a common workflow.',`<div class="quick-actions">${quick('▣','POS Sale','Start billing','sales')}${quick('◇','Product','Add item','products','add-product')}${quick('⇩','Stock','Post adjustment','inventory','stock-adjust')}${quick('↥','Bulk Data','Excel paste','bulk')}</div>`,'','small');setTimeout(()=>$$('.modal [data-quick-route]').forEach(b=>b.onclick=()=>{document.querySelector('.modal-backdrop')?.remove();route=b.dataset.quickRoute;renderApp();setTimeout(()=>{if(b.dataset.action==='add-product')openProduct();if(b.dataset.action==='stock-adjust')openStockAdjustment()},0)}),0);}
function openProfileMenu(){const body=`<div class="mini-list"><div class="mini-item"><div><strong>${esc(me().displayName)}</strong><span>${roleLabel(me().role)} • ${esc(shop().name)}</span></div><div class="avatar">${initials(me().displayName)}</div></div><div class="mini-item"><span>Session mode</span><span class="badge">${esc(state.session.mode)}</span></div></div>`;const m=modal('Account','Session and workspace controls.',body,`<button class="btn" id="go-settings">Settings</button><button class="btn danger" id="logout">Sign Out</button>`,'small');$('#go-settings',m).onclick=()=>{m.remove();route='settings';renderApp()};$('#logout',m).onclick=async()=>{if(state.session.mode==='supabase')await supabaseLogout();state.session=null;saveState(state);m.remove();renderApp()};}
function exportJSON(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`hardware-erp-demo-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Demo data exported');}

window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search')?.focus();}});
renderApp();

if ('serviceWorker' in navigator && location.protocol !== 'file:') window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
